import { approvePayment, recordPayment, rejectPayment } from '../../../../../../home/electronica-care/ezy-prep/exam/app/src/server/services/payments'

const manager = { userId: '0815019d-9742-4aac-8ba3-9101ec716ad1' }
const staff = { userId: 'c4cd5237-066c-43ca-98dc-3c13f476cf25' }
const leaseId = 'da72a5cd-a582-43da-86cb-20d7d318196d'
const orgId = '1a21e89d-48f3-48e2-9af7-acc5de59d1cb'
const otherLease = '7e8507de-f879-41f9-a519-fd4f91fcca06'

async function show(label: string, fn: () => Promise<unknown>): Promise<void> {
  try {
    console.log(label, 'OK', JSON.stringify(await fn()))
  } catch (e) {
    const res = toErrorResponse(e)
    console.log(label, res.status, await res.text())
  }
}

async function main(): Promise<void> {
  await show('over cap', () => recordPayment(manager, leaseId, { amountSen: 99999999, method: 'cash', receivedAt: '2026-01-31T10:00:00+08:00' }))
  await show('missing slip', () =>
    recordPayment(staff, leaseId, { amountSen: 100, method: 'bank_transfer', receivedAt: '2026-01-31T10:00:00+08:00', slipPath: `${orgId}/${leaseId}/nope.pdf` }),
  )
  await show('naive receivedAt', () => recordPayment(manager, leaseId, { amountSen: 100, method: 'cash', receivedAt: '2026-01-31T10:00:00' }))
  await show('cash with slip', () => recordPayment(manager, leaseId, { amountSen: 100, method: 'cash', receivedAt: '2026-01-31T10:00:00Z', slipPath: `${orgId}/x.pdf` }))
  await show('foreign slip prefix', () =>
    recordPayment(manager, leaseId, { amountSen: 100, method: 'bank_transfer', receivedAt: '2026-01-31T10:00:00Z', slipPath: 'other/x.pdf' }),
  )
  await show('extra key', () => recordPayment(manager, leaseId, { amountSen: 100, method: 'cash', receivedAt: '2026-01-31T10:00:00Z', x: 1 }))
  await show('bad idem key', () => recordPayment(manager, leaseId, { amountSen: 100, method: 'cash', receivedAt: '2026-01-31T10:00:00Z' }, { idempotencyKey: 'abc' }))
  await show('other org lease', () => recordPayment(manager, otherLease, { amountSen: 100, method: 'cash', receivedAt: '2026-01-31T10:00:00Z' }))
  await show('approve missing', () => approvePayment(manager, '00000000-0000-4000-8000-000000000000'))
  await show('reject malformed id', () => rejectPayment(manager, 'nope', { reason: 'abc' }))
  process.exit(0)
}

void main()

